    ['slug' => 'contractor-work-order-format', 'cat' => $C, 'type' => 'doc', 'icon' => 'file-pen-line',
     'en' => 'Contractor Work Order Format', 'gu' => 'કોન્ટ્રાક્ટર વર્ક ઓર્ડર ફોર્મેટ',
     'de' => 'Issue a printable work order to a sub-contractor or labour contractor with scope, rate, timeline, retention and terms.',
     'dg' => 'પેટા-કોન્ટ્રાક્ટર કે મજૂર કોન્ટ્રાક્ટરને કામનો વ્યાપ, ભાવ, સમયમર્યાદા, રિટેન્શન અને શરતો સાથે છાપી શકાય તેવો વર્ક ઓર્ડર આપો.',
     'in' => [
       ['k' => 'no', 'en' => 'Work order no.', 'gu' => 'વર્ક ઓર્ડર નં.', 'v' => 'WO-2026-14', 't' => 'text'],
       ['k' => 'date', 'en' => 'Date', 'gu' => 'તારીખ', 't' => 'date'],
       ['k' => 'con', 'en' => 'Contractor name', 'gu' => 'કોન્ટ્રાક્ટરનું નામ', 'v' => 'Mahadev Labour Contractor', 't' => 'text'],
       ['k' => 'work', 'en' => 'Work description', 'gu' => 'કામનું વર્ણન', 'v' => 'Brickwork and internal plaster of A-wing', 't' => 'text'],
       ['k' => 'site', 'en' => 'Site', 'gu' => 'સાઇટ', 'v' => 'Shree Residency', 't' => 'text'],
       ['k' => 'rate', 'en' => 'Rate', 'gu' => 'ભાવ', 'v' => '₹28 per sq ft of plaster, ₹55 per cft brickwork', 't' => 'text'],
       ['k' => 'start', 'en' => 'Start date', 'gu' => 'શરૂઆત તારીખ', 't' => 'date'],
       ['k' => 'end', 'en' => 'Completion within', 'gu' => 'પૂરું કરવાની મુદત', 'v' => '60 days', 't' => 'text'],
       ['k' => 'ret', 'en' => 'Retention', 'gu' => 'રિટેન્શન', 'v' => '5%', 't' => 'text'],
     ],
     'doc' => ['title_en' => 'Work Order', 'title_gu' => 'વર્ક ઓર્ડર',
       'body_en' => "To,\n{con}\n\nSubject: Work order for {work} at {site}\n\nWe are pleased to award you the above work on the following terms:\n1. Rate: {rate}. Measurement will be taken jointly at site.\n2. Work to start on {start} and be completed within {end}.\n3. Work must follow the drawings and instructions of our site engineer; all safety rules must be followed by your workers.\n4. {ret} of each bill will be retained and released after the defect liability period.\n5. Running bills will be paid within 7 days of certification, after TDS as applicable.\n6. Any damage or wastage of material due to negligence will be recovered from your bill.\n\nPlease sign and return a copy as your acceptance.",
       'body_gu' => "પ્રતિ,\n{con}\n\nવિષય: {site} ખાતે {work} માટે વર્ક ઓર્ડર\n\nઉપરોક્ત કામ નીચેની શરતોએ આપને સોંપતાં આનંદ થાય છે:\n1. ભાવ: {rate}. માપણી સાઇટ પર સંયુક્ત રીતે થશે.\n2. કામ {start} થી શરૂ કરી {end} માં પૂરું કરવાનું રહેશે.\n3. કામ અમારા સાઇટ એન્જિનિયરના ડ્રોઇંગ અને સૂચના મુજબ કરવાનું રહેશે; તમારા કારીગરોએ સલામતીના બધા નિયમો પાળવાના રહેશે.\n4. દરેક બિલમાંથી {ret} રિટેન્શન રોકાશે, જે ડિફેક્ટ લાયબિલિટી સમયગાળા પછી છૂટશે.\n5. રનિંગ બિલ પ્રમાણિત થયાના 7 દિવસમાં લાગુ TDS કાપીને ચૂકવાશે.\n6. બેદરકારીથી માલનું નુકસાન કે બગાડ થશે તો તે બિલમાંથી વસૂલ થશે.\n\nસ્વીકૃતિ તરીકે નકલ પર સહી કરી પરત કરશો.",
       'sign' => true],
     'faq' => [
       ['Why give a written work order?', 'It fixes the rate, scope, time and deductions in advance and avoids disputes during billing.', 'લેખિત વર્ક ઓર્ડર કેમ આપવો?', 'તેનાથી ભાવ, કામનો વ્યાપ, સમય અને કપાત પહેલેથી નક્કી થાય અને બિલિંગ વખતે ઝઘડા ટળે.'],
     ]],

